"""W4: consolidated results tables -> results/FINAL_TABLES.md (generated; do not edit by hand)."""
import json

import pandas as pd

from config import RESULTS


def ci(r, m="auroc"):
    return f"{r[m]:.3f} [{r[m + '_lo']:.3f}, {r[m + '_hi']:.3f}]"


def main():
    out = ["# Final tables", "",
           "Generated by `src/final_tables.py` from the committed CSVs. Cells: point [95% bootstrap CI] unless noted. "
           "Feature space: the backdoored (LoRA) model unless noted (D9).", ""]

    # 0. organism
    bc = json.load(open(RESULTS / "backdoor_check_v3.json"))
    out += ["## T0. Backdoor model organism (v3, accepted; D16, D17)", "",
            "| prompts (n=300) | validation | test |", "|---|---|---|",
            f"| triggered | {bc['val_triggered']:.1%} | {bc['test_triggered']:.1%} |",
            f"| untriggered | {bc['val_untriggered']:.1%} | {bc['test_untriggered']:.1%} |",
            f"| control phrase | {bc['val_control_phrase']:.1%} | {bc['test_control_phrase']:.1%} |",
            f"| base model, triggered | — | {bc['base_test_triggered']:.1%} |", ""]

    # 1. primary
    out += ["## T1. Primary comparison (PROTOCOL §4 + A1)", "",
            "Δ = AUROC(NMF k=32) − max(AUROC(PCA k=32), AUROC(Mahalanobis)); 99.375% paired bootstrap interval "
            "(Bonferroni over 8 cells per type). Verdict: better / worse if the interval excludes 0.", "",
            "| type | layer | features | pooling | NMF | PCA | Mahalanobis | Δ [99.375%] | verdict (A1) | verdict (original, mean only) |",
            "|---|---|---|---|---|---|---|---|---|---|"]
    for t in ["A", "B"]:
        p = pd.read_csv(RESULTS / f"primary_{t}.csv")
        for r in p.itertuples():
            orig = r.original_verdict if isinstance(r.original_verdict, str) else "—"
            out.append(f"| {t} | {r.layer} | {r.features} | {r.pooling} | {r.auroc_nmf:.3f} | {r.auroc_pca:.3f} | "
                       f"{r.auroc_maha:.3f} | {r.delta:+.3f} [{r.amended_lo:+.3f}, {r.amended_hi:+.3f}] | "
                       f"{r.amended_verdict} | {orig} |")
    out.append("")

    # 2. controls at the dev-selected configuration
    m = pd.read_csv(RESULTS / "metrics_w3.csv")
    sel = m[(m.model == "lora") & (m.layer == 18) & (m.features == "resid_split") & (m.pooling == "last")]
    base = m[(m.model == "base") & (m.layer == 18) & (m.features == "resid_split") & (m.pooling == "last")]
    sets = ["A_test", "A_ctrl", "A_base", "NC_near_lenstrat", "A_vs_NCnear_lenstrat", "B_test", "NC_far", "B_vs_NCfar"]
    out += ["## T2. All evaluation sets at layer 18, last token, residual split (AUROC)", "",
            "This configuration was selected on backdoor dev data for every unsupervised family "
            "(`crosstype.csv`). `A_base` uses base-model features. `*_lenstrat` sets are length-stratified (A2). "
            "`*_vs_NC*` sets have the negative control as negatives (PROTOCOL §5: lower bound > 0.5 is required).", "",
            "| detector | " + " | ".join(sets) + " |", "|---|" + "---|" * len(sets)]
    for det in ["nmf_k32", "rnmf_k32", "pca_k32", "mahalanobis", "sae", "length"]:
        cells = []
        for s in sets:
            src = base if s == "A_base" else sel
            r = src[(src.detector == det) & (src.eval_set == s)]
            cells.append(ci(r.iloc[0]) if len(r) else "n/a")
        out.append(f"| {det} | " + " | ".join(cells) + " |")
    out.append("")

    # 3. TPR@1% FPR at the same configuration
    out += ["## T3. TPR at 1% FPR, same configuration", "",
            "| detector | A_test | A_ctrl | NC_near | B_test | NC_far |", "|---|---|---|---|---|---|"]
    pr = pd.read_csv(RESULTS / "probe.csv")
    prs = pr[(pr.model == "lora") & (pr.layer == 18) & (pr.features == "resid_split") & (pr.pooling == "last")]
    for det in ["nmf_k32", "rnmf_k32", "pca_k32", "mahalanobis", "sae", "length", "probe_A", "probe_B"]:
        cells = []
        for s in ["A_test", "A_ctrl", "NC_near", "B_test", "NC_far"]:
            r = prs[(prs.train_type == det[-1]) & (prs.test_set == s)] if det.startswith("probe") else \
                sel[(sel.detector == det) & (sel.eval_set == s)]
            cells.append(ci(r.iloc[0], "tpr@1%fpr") if len(r) else "n/a")
        out.append(f"| {det} | " + " | ".join(cells) + " |")
    out.append("")

    # 4. probes
    out += ["## T4. Supervised probe: AUROC on test (trained on one type's dev set, C by grouped CV; D24, D27, D28)", "",
            "| model | layer | features | pooling | train | C | A_test | B_test |", "|---|---|---|---|---|---|---|---|"]
    for (mod, L, f, pool, tt), g in pr.groupby(["model", "layer", "features", "pooling", "train_type"]):
        a = g[g.test_set == "A_test"]
        b = g[g.test_set == "B_test"]
        out.append(f"| {mod} | {L} | {f} | {pool} | {tt} | {g.C.iloc[0]:g} | {ci(a.iloc[0]) if len(a) else 'n/a'} | "
                   f"{ci(b.iloc[0]) if len(b) else 'n/a'} |")
    out.append("")

    # 5. cross-type selection
    ct = pd.read_csv(RESULTS / "crosstype.csv")
    out += ["## T5. Cross-type selection, unsupervised (PROTOCOL §6, D25)", "",
            "| family | selected on | chosen config | dev AUROC | A_test AUROC | B_test AUROC |", "|---|---|---|---|---|---|"]
    for r in ct.itertuples():
        out.append(f"| {r.family} | {r.selected_on} dev | L{r.layer} {r.features} {r.pooling} {r.detector} | {r.dev_auroc:.3f} | "
                   f"{r.A_test_auroc:.3f} [{r.A_test_lo:.3f}, {r.A_test_hi:.3f}] | {r.B_test_auroc:.3f} [{r.B_test_lo:.3f}, {r.B_test_hi:.3f}] |")
    out.append("")

    # 6. rank sweep
    sw = m[(m.model == "lora") & m.eval_set.isin(["A_test", "B_test"]) & m.detector.str.match(r"(pca|nmf|rnmf)_k")]
    piv = sw.pivot_table(index=["eval_set", "layer", "features", "pooling"], columns="detector", values="auroc")
    cols = [f"{f}_k{k}" for f in ["pca", "nmf", "rnmf"] for k in (8, 16, 32, 64)]
    out += ["## T6. Rank sweep (AUROC point estimates)", "", piv[cols].round(3).to_markdown(), ""]

    # 7. nonnegativity diagnostics
    nn = json.load(open(RESULTS / "nonneg_check.json"))
    out += ["## T7. Nonnegativity diagnostics (200 benign_val prompts, backdoored model)", "",
            "| layer | GELU squared mass removed by clipping | GELU entries < 0 | [x+, x−] entries = 0 |", "|---|---|---|---|"]
    for L in ["L12", "L18"]:
        d = nn[L]
        out.append(f"| {L} | {d['mlp_relu_sq_mass_clipped']:.1%} | {d['mlp_relu_frac_entries_negative']:.1%} | "
                   f"{d['resid_split_frac_entries_zero']:.1%} |")
    out.append("")
    commits = {pd.read_csv(RESULTS / f).commit.iloc[0] for f in ["metrics_w3.csv", "primary_A.csv", "primary_B.csv", "probe.csv"]}
    out.append(f"Source commits: {', '.join(sorted(commits))}.")
    (RESULTS / "FINAL_TABLES.md").write_text("\n".join(out) + "\n")
    print(f"wrote {RESULTS / 'FINAL_TABLES.md'}")


if __name__ == "__main__":
    main()
